import hashlib

import pytest

from hebocon import vdoninja


def test_default_password_appends_hash():
    target = vdoninja.parse("https://vdo.ninja/?view=friendtinyQ")
    digest = hashlib.sha256(b"someEncryptionKey123vdo.ninja").digest()
    assert target.stream_id == "friendtinyQ" + digest.hex()[:6]
    assert target.key == digest


@pytest.mark.parametrize("pw", ["false", "0", ""])
def test_password_off(pw):
    target = vdoninja.parse(f"vdo.ninja/?view=abc&password={pw}")
    assert target == vdoninja.Target("abc", None)


def test_fragment_and_custom_password():
    target = vdoninja.parse("https://vdo.ninja/#view=abc&pw=x&p=geheim")
    assert target.stream_id.startswith("abc")
    assert target.key == hashlib.sha256(b"geheimvdo.ninja").digest()


def test_missing_view():
    with pytest.raises(vdoninja.NinjaError):
        vdoninja.parse("https://vdo.ninja/?room=x")


def test_encrypt_roundtrip():
    key = hashlib.sha256(b"k").digest()
    data, vector = vdoninja.encrypt(key, '{"a":"ü"}')
    assert vdoninja.decrypt(key, data, vector) == '{"a":"ü"}'


def test_detects_links():
    assert vdoninja.looks_like_ninja("https://vdo.ninja/?view=x")
    assert not vdoninja.looks_like_ninja("rtsp://cam/stream")
